// state: () => ({ n: 0 })
// mutations: { INCREMENT(s) { s.n++ }, SET(s, v) { s.n = v } }
// actions: { inc({ commit }) { commit('INCREMENT') }, reset({ commit }) { commit('SET', 0) } }
// getters: { double: (s) => s.n * 2 }

// TODO: Pinia version

exercise.solution:
import { defineStore } from 'pinia'

export const useCounterStore = defineStore('counter', {
  state: () => ({ n: 0 }),
  getters: {
    double: (state) => state.n * 2
  },
  actions: {
    inc() {
      this.n += 1
    },
    reset() {
      this.n = 0
    }
  }
})
